// Regenerates src/admin_page.js from admin/admin.html (run after editing the dashboard).
import { readFileSync, writeFileSync } from "node:fs";
const html = readFileSync(new URL("./admin/admin.html", import.meta.url), "utf8");
writeFileSync(new URL("./src/admin_page.js", import.meta.url),
  "// Generated by build_admin.mjs from admin/admin.html - edit that file instead.\nexport const ADMIN_HTML = " + JSON.stringify(html) + ";\n");
